  static ServiceItem? byId(String id) {
    for (final s in services) {
      if (s.id == id) return s;
    }
    return null;
  }

  static List<ServiceItem> byCategory(String categoryId) =>
      services.where((s) => s.categoryId == categoryId).toList();

